package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        int terms = terms(person, settings);
        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
        if (periods.closedOn(person.sheetId(), dueBy)) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        checkRef(person.sheetId(), values, null, claims);
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
    }

    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
     *  claim being edited (null for an add), whose own reference does not count. */
    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
        }
    }

    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
     *  HolidayRepository.businessDaysAfter), the terms being those in force on the day it is added (see terms; the
     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, settings));
    }

    /** The terms a claim of the person is fixed with as it is added, whatever its date: those in force on the day it is added (the sheet's
     *  today) — the person's own in force on that day, else those of the grade they had that day in force on it, else the sheet's. The claim
     *  keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
    public static int terms(Person person, SettingRepository settings) {
        LocalDate today = settings.today(person.sheetId());
        return settings.terms(person.sheetId(), person.termsOn(today), person.gradeOn(today), today);
    }

    /** Whether opening the claim would take its person past the cap of the period its due-by falls in: they already have
     *  that many OPEN or PENDING claims in it (a period with no cap, or no period: never). */
    public static boolean overCap(Claim claim, PeriodRepository periods, ClaimRepository claims) {
        Period period = periods.containing(claim.sheetId(), claim.dueBy());
        return period != null && period.cap() != null
                && claims.heldIn(claim.sheetId(), claim.personId(), period.from(), period.to()) >= period.cap();
    }

    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;

/** The figures a claim has: live, fixed when settled, or bound by a statement. */
public final class ClaimDue {

    private ClaimDue() {
    }

    /** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do. */
    public static boolean counts(Claim claim) {
        return isOpen(claim) || claim.status() == ClaimStatus.SETTLED;
    }

    /** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim). */
    public static boolean isOpen(Claim claim) {
        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING;
    }

    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts. A
     *  hold (the claim's or its person's) does not take it out; a hold only takes a person's cut in the pools. */
    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person) {
        return counts(claim);
    }

    /** Whether a claim is deferred on the given today: an OPEN claim deferred until a date after it. Until then it
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement; from that day on
     *  it is an OPEN claim like any other. */
    public static boolean deferred(Claim claim, java.time.LocalDate today) {
        return claim.status() == ClaimStatus.OPEN && claim.deferredUntil() != null
                && claim.deferredUntil().isAfter(today);
    }

    /** Whether a claim counts toward the live totals on the given today: as {@link #countsLive(Claim,
     *  net.officefloor.hq.app.person.Person)}, unless it is deferred, or it is open, not bound by a statement, and its
     *  person's retirement date is reached on today. */
    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person,
            java.time.LocalDate today) {
        return countsLive(claim, person) && !deferred(claim, today) && !retiredOut(claim, person, today);
    }

    /** Whether a claim counts toward claimed (a person's claimed, the claimed-total) on the given today: as {@link
     *  #countsLive(Claim, net.officefloor.hq.app.person.Person, java.time.LocalDate)}, which it now matches. */
    public static boolean countsClaimed(Claim claim, net.officefloor.hq.app.person.Person person,
            java.time.LocalDate today) {
        return counts(claim) && !deferred(claim, today) && !retiredOut(claim, person, today);
    }

    /** Whether a claim leaves the live totals for its person's retirement: it is open (OPEN or PENDING), not bound by
     *  a statement, and its person's retirement date is on or before today (null person: never). */
    public static boolean retiredOut(Claim claim, net.officefloor.hq.app.person.Person person,
            java.time.LocalDate today) {
        return isOpen(claim) && !bound(claim) && person != null && person.retiredOn(today);
    }

    /** The claim's rate figure: its amount at the grade's rate that applies to it on its date (a forward-only rate
     *  saved after it was added does not; see RateRepository#forClaim), rounded to two decimals by the
     *  claim's rounding (see Rounding); null when no rate applies. The floor is applied to it before the late charge
     *  (see LateCharge#add). */
    public static BigDecimal live(Claim claim, String grade, RateRepository rates, Rounding rounding) {
        Rate rate = rates.forClaim(claim.sheetId(), grade, claim.date(), rates.seqOf(claim.id()));
        if (rate == null) {
            return null;
        }
        return claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, rounding.mode(claim));
    }

    /** Whether the claim is a correction: its amount is negative. */
    public static boolean isCorrection(Claim claim) {
        return claim.amount().signum() < 0;
    }

    /** The figure the claim shows: fixed when settled, else the one a statement bound it to (PENDING included),
     *  else its live rate figure; null when it has none (n/a). */
    public static BigDecimal figure(Claim claim, String grade, RateRepository rates, Rounding rounding) {
        if (claim.due() != null) {
            return claim.due();
        }
        return bound(claim) ? claim.statedDue() : live(claim, grade, rates, rounding);
    }

    /** Whether the claim keeps a figure whatever the rates are: fixed when settled, or bound by a statement. */
    public static boolean kept(Claim claim) {
        return claim.due() != null || (bound(claim) && claim.statedDue() != null);
    }

    /** Whether a statement binds the claim now: it is stated (PENDING included, like any claim that counts). */
    public static boolean bound(Claim claim) {
        return claim.stated();
    }

    /** The status a claim had at the end of a day, as its status log (oldest first) records it: that of the last line
     *  made on or before the day; null when the claim was added after it. */
    public static ClaimStatus statusAsOf(java.util.List<ClaimLogLine> log, java.time.LocalDate day) {
        ClaimStatus status = null;
        for (ClaimLogLine line : log) {
            if (!line.date().isAfter(day)) {
                status = line.status();
            }
        }
        return status;
    }

    /** The claim as it would be with another status, all else kept. */
    public static Claim withStatus(Claim c, ClaimStatus status) {
        return new Claim(c.id(), c.sheetId(), c.personId(), c.amount(), c.date(), c.note(), status, c.number(), c.due(),
                c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(), c.proofs(), c.splitFrom(), c.ref(), c.tags(), c.held());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.statement.SheetAsOf;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementRepository;

/**
 * A claim's due as it stood at the end of a date, as the as-of view works it out (see AsOf, RespondWithClaims): every
 * change made while the sheet's today was on or before the date counts (the claim's status its log shows then, its
 * values before any later edit, its deferral, its person's grades, the rates and settings, a statement binding it),
 * and the date stands in for the sheet's today, late charge and floor included.
 */
public final class ClaimDueAsOf {

    private ClaimDueAsOf() {
    }

    /** The claim's due at the end of the date; throws when the claim was not yet on the sheet then. The due is the
     *  figure (null: n/a) in the result. */
    public static Figure of(Claim claim, LocalDate date, ClaimRepository claims, ClaimLogRepository log,
            PersonRepository people, RateRepository rates, SettingRepository settings, StatementRepository statements)
            throws InvalidClaimStatusException {
        String sheetId = claim.sheetId();
        List<ClaimLogLine> lines = log.of(sheetId, claim.id());
        ClaimStatus status = lines.isEmpty() ? claim.status() : ClaimDue.statusAsOf(lines, date);
        if (status == null) {
            throw new InvalidClaimStatusException("The claim was not on the sheet on " + date);
        }
        Person current = people.find(sheetId, claim.personId());
        Person person = current == null ? null : people.asOf(current, date);
        SheetAsOf sheet = SheetAsOf.read(sheetId, date, rates, settings);
        LocalDate policy = sheet.policyDate();
        Rounding rounding = new Rounding(policy == null ? date : policy, claims,
                (on) -> sheet.value(SettingRepository.ROUNDING, on));
        LateCharge late = new LateCharge(date, sheet::latePct, rounding,
                (c) -> sheet.grace(person == null ? null : person.gradeOn(c.date()), c.date()),
                LateCharge.waivedIn(claims.waived(sheetId, date)));
        Claim values = claims.editedAfter(sheetId, date).getOrDefault(claim.id(), claim);
        var deferred = claims.deferredAsOf(sheetId, date);
        Statement last = claim.stated() ? statements.last(sheetId, claim.personId()) : null;
        boolean stated = last != null && AsOf.counts(last.madeOn(), date);
        Claim then = new Claim(claim.id(), sheetId, claim.personId(), values.amount(), values.date(), values.note(),
                status, claim.number(), status == ClaimStatus.SETTLED ? claim.due() : null, claim.openedBy(), stated,
                stated ? claim.statedDue() : null, values.corrects(), claim.dueBy(),
                deferred.containsKey(claim.id()) ? deferred.get(claim.id()) : claim.deferredUntil(), claim.proofs(),
                claim.splitFrom(), values.ref(), values.tags(), claim.held());
        if (person == null) {
            return new Figure(then.due());
        }
        return new Figure(late.add(then, figure(then, person.gradeOn(then.date()), sheet, rounding, rates),
                sheet.floor(then.date())));
    }

    /** The figure the claim had then (see ClaimDue#figure), at the rate in force then on its date. */
    private static BigDecimal figure(Claim c, String grade, SheetAsOf sheet, Rounding rounding, RateRepository rates) {
        if (c.due() != null) {
            return c.due();
        }
        if (ClaimDue.bound(c)) {
            return c.statedDue();
        }
        Rate rate = sheet.rate(grade, c.date(), rates.seqOf(c.id()));
        if (rate == null) {
            return null;
        }
        RoundingMode mode = rounding.mode(c);
        return c.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, mode);
    }

    /** A due worked out as of a date; its value is null when it is n/a. */
    public record Figure(BigDecimal value) {
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.function.Function;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * How a claim's live figures (the rate step and the late charge) are rounded to two decimals: a claim dated before
 * the sheet's policy date (its today while the policy date is blank) rounds half up, one dated on or after it half to
 * even; unless a rounding mode (the dated setting rounding, half-up or half-even) is in force on its date, when it rounds
 * by that mode. A correction rounds by the date of the claim it corrects, not its own.
 */
public record Rounding(LocalDate policy, ClaimRepository claims, Function<LocalDate, String> modeOn) {

    public static Rounding of(String sheetId, SheetRepository sheets, SettingRepository settings, ClaimRepository claims) {
        LocalDate policy = settings.policyDate(sheetId);
        return new Rounding(policy == null ? sheets.today(sheetId) : policy, claims,
                (date) -> settings.value(sheetId, SettingRepository.ROUNDING, date));
    }

    /** The date that decides how the claim rounds: the corrected claim's date for a correction, else its own. */
    public static LocalDate roundsOn(Claim claim, ClaimRepository claims) {
        if (claim.corrects() != null) {
            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
            if (corrected != null) {
                return corrected.date();
            }
        }
        return claim.date();
    }

    /** The rounding the claim's live figures take. */
    public RoundingMode mode(Claim claim) {
        LocalDate on = roundsOn(claim, claims);
        String mode = modeOn.apply(on);
        if (SettingRepository.HALF_UP.equals(mode)) {
            return RoundingMode.HALF_UP;
        }
        if (SettingRepository.HALF_EVEN.equals(mode)) {
            return RoundingMode.HALF_EVEN;
        }
        return on.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.Function;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The late charge on a sheet as of its today: an overdue claim (OPEN or PENDING, its due-by — fixed when it was added — plus
 * its grace before today; see lateFrom) gains, for every full 30 days it is overdue, the late percent in force on that boundary
 * date (its due-by plus its grace plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries before it (compounding), each rounded to two decimals by the claim's rounding (see Rounding), added up; a
 * boundary whose percent is 0.00 adds nothing. A statement binds the claim's due as shown, the charge included: while
 * bound it no longer follows today (see #add); settling freezes it into the claim's due.
 * A claim whose late charge a steward waived bears none (see ApplyWaive).
 * The floor is applied first: a claim's live due is its figure floored (the greater of it and the floor in force on its date)
 * plus the charge worked out on that floored figure.
 */
public record LateCharge(LocalDate today, Function<LocalDate, BigDecimal> pct, Rounding rounding,
        Function<Claim, Integer> grace, java.util.function.Predicate<Claim> waived) {

    /** The days in each step of the charge. */
    public static final int DAYS = 30;

    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings,
            ClaimRepository claims) {
        return new LateCharge(sheets.today(sheetId), (date) -> settings.latePct(sheetId, date),
                Rounding.of(sheetId, sheets, settings, claims),
                (claim) -> settings.graceOf(sheetId, claim.personId(), claim.date()),
                waivedIn(claims.waived(sheetId, null)));
    }

    /** Whether a claim is waived: its id is among the given ones. */
    public static java.util.function.Predicate<Claim> waivedIn(java.util.Set<Long> ids) {
        return (claim) -> ids.contains(claim.id());
    }

    /** The date a claim is late from: its due-by plus the grace of its person's grade in force on its date (none: its
     *  due-by). The claim is overdue once this is before today; its 30-day boundaries count from it. */
    public LocalDate lateFrom(Claim claim) {
        return claim.dueBy().plusDays(grace.apply(claim));
    }

    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, is
     *  a correction, is deferred, or is waived. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)
                || ClaimDue.deferred(claim, today) || waived.test(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        LocalDate from = lateFrom(claim);
        long overdue = ChronoUnit.DAYS.between(from, today);
        long steps = overdue <= 0 ? 0 : overdue / DAYS;
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long step = 1; step <= steps; step++) {
            BigDecimal boundary = pct.apply(from.plusDays(step * DAYS));
            charge = charge.add(figure.add(charge).multiply(boundary).movePointLeft(2).setScale(2, rounding.mode(claim)));
        }
        return charge;
    }

    /** The claim's due: the figure, at least the floor (none for a correction, nor for a settled figure, which stays
     *  frozen), with the charge on that floored figure added on top; null when it has none. A claim bound by a statement (not settled) has the
     *  due it was bound to, its figure, as it is. */
    public BigDecimal add(Claim claim, BigDecimal figure, BigDecimal floor) {
        if (figure == null) {
            return null;
        }
        if (claim.due() == null && ClaimDue.bound(claim)) {
            return figure;
        }
        BigDecimal floored = claim.due() != null || ClaimDue.isCorrection(claim) ? figure : figure.max(floor);
        return floored.add(on(claim, floored));
    }
}
